 if($('resumeDraft'))$('resumeDraft').onclick=()=>{if(normalizeName($('playerName').value)!==profile.name){$('mapMessage').textContent='برای تغییر بازیکن، ابتدا شروع ماجراجویی یا ادامهٔ سفر را بزن.';$('playerName').focus();return;}openLesson(resume.stage);openTask(resume.index);};
 if($('discardDraft'))$('discardDraft').onclick=()=>{if(normalizeName($('playerName').value)!==profile.name){$('playerName').focus();return;}if(!confirm('پاسخ نیمه‌کاره پاک شود؟ پیشرفت و سابقهٔ راهنمایی حفظ می‌شوند.'))return;taskDrafts.delete(JSON.stringify([profile.name,stages[resume.stage].tasks[resume.index].id]));persistDrafts();openLesson(resume.stage);openTask(resume.index);};
 $('startForm').onsubmit=e=>{e.preventDefault();const name=normalizeName($('playerName').value);if(!name){$('playerName').focus();return;}loadProfile(name);const i=stages.findIndex(s=>count(s)<4);openLesson(i<0?0:i);};
