function taskUI(t){if(t.type==='grid')return gridUI(t);if(t.type==='axes')return `<figure class="shape-figure" id="axisFigure">${shapeSVG(t.shape)}</figure><p class="multi-note">همهٔ خط‌های درست را انتخاب کن.</p><div class="axis-options">${[['v','عمودی ↕'],['h','افقی ↔'],['d','مایل از بالاچپ به پایین‌راست ╲'],['u','مایل از پایین‌چپ به بالاراست ╱']].map(([id,label])=>`<button class="option" data-axis="${id}" aria-pressed="false">${label}</button>`).join('')}</div>`;if(t.type==='angle')return `<div class="shape-figure" id="angleFigure">${angleSVG(t.total,0)}</div><div class="angle-console"><label for="angleRange">زاویهٔ پرتو بنفش از ضلع افقی</label><div class="angle-precision"><button class="secondary" id="angleMinus" aria-label="یک درجه کمتر" disabled>−۱°</button><output id="angleOutput" for="angleRange">۰ درجه</output><button class="secondary" id="anglePlus" aria-label="یک درجه بیشتر">+۱°</button></div><input id="angleRange" type="range" min="0" max="${t.total}" value="0" step="1" aria-valuetext="۰ درجه"><div class="angle-scale" aria-hidden="true"><span>۰°</span><span>${fa(t.total)}°</span></div><p>برای حرکت دقیق، از دکمه‌های یک‌درجه‌ای یا کلیدهای جهت‌دار استفاده کن.</p></div>`;if(t.type==='number')return `${diagram(t)}<label class="number-answer">پاسخ تو<input class="text-input" id="numberInput" inputmode="decimal" autocomplete="off" placeholder="عدد" aria-label="پاسخ عددی؛ اعداد فارسی یا انگلیسی"></label>`;return `${diagram(t)}${t.type==='properties'?'<p class="multi-note">ممکن است چند گزینه درست باشد؛ همهٔ گزینه‌های درست را انتخاب کن.</p>':''}<div class="choices">${t.options.map((o,i)=>`<button class="option" data-choice="${i}" aria-pressed="false">${o}</button>`).join('')}</div>`;}
function taskNavigation(){const s=stages[stageIndex];return `<nav class="task-route" aria-label="تمرین‌های این ایستگاه">${s.tasks.map((t,i)=>`<button class="route-stop ${profile.done[t.id]?'is-done':''}" data-task-jump="${i}" ${i===taskIndex?'aria-current="step"':''}><b>${fa(i+1)}</b><span>تمرین ${fa(i+1)}<small>${profile.done[t.id]?'✓ انجام شده':i===taskIndex?'در حال تمرین':'آمادهٔ شروع'}</small></span></button>`).join('')}</nav><p class="route-note">انتخاب هر شماره: رفتن به همان تمرین؛ پاسخ نیمه‌کاره هنگام جابه‌جایی حفظ می‌شود؛ در صورت دسترسی به ذخیرهٔ مرورگر، پس از بستن صفحه هم قابل ادامه است.</p>`;}
function validDraftValue(t,v){if(t.type==='grid')return Array.isArray(v)&&v.length<=81&&new Set(v).size===v.length&&v.every(x=>typeof x==='string'&&/^[0-8],[0-8]$/.test(x));if(t.type==='axes'||t.type==='properties')return Array.isArray(v)&&v.length<=8&&new Set(v).size===v.length&&v.every(x=>t.type==='axes'?['v','h','d','u'].includes(x):Number.isInteger(x)&&x>=0&&x<t.options.length);if(t.type==='angle')return Number.isInteger(v)&&v>=0&&v<=t.total;if(t.type==='number')return v===null||typeof v==='string'&&v.length<=100;return v===null||Number.isInteger(v)&&v>=0&&v<t.options.length;}
function loadDrafts(){try{const raw=localStorage.getItem(PREFIX+'drafts.'+profile.name);if(!raw||raw.length>600000)return;const data=JSON.parse(raw);if(data?.version!==1||!Array.isArray(data.items)||data.items.length>48)return;const ids=new Set(stages.flatMap(s=>s.tasks.map(t=>t.id)));if(Array.isArray(data.guided))data.guided.slice(0,48).forEach(id=>{if(ids.has(id))guidedTaskMemory.add(JSON.stringify([profile.name,id]));});for(const d of data.items){if(!d||!Number.isInteger(d.stage)||!Number.isInteger(d.index)||d.stage<0||d.stage>=stages.length||d.index<0||d.index>3)continue;const t=stages[d.stage].tasks[d.index];if(!validDraftValue(t,d.value)||!Number.isInteger(d.attempts)||d.attempts<0||d.attempts>100000||!Number.isInteger(d.hints)||d.hints<0||d.hints>100000)continue;const history=x=>Array.isArray(x)&&x.length<=100&&x.every(v=>t.type==='grid'&&validDraftValue(t,v))?x:[];taskDrafts.set(JSON.stringify([profile.name,t.id]),{stage:d.stage,index:d.index,value:d.value,attempts:d.attempts,hints:d.hints,past:history(d.past),future:history(d.future),start:Date.now()});}}catch(e){/* Ignore invalid or unavailable storage; in-memory play remains available. */}}
function persistDrafts(){if(!profile.name||restoringDraft)return;const items=[...taskDrafts.entries()].filter(([key])=>JSON.parse(key)[0]===profile.name).map(([,d])=>d);const guided=[...guidedTaskMemory].map(k=>JSON.parse(k)).filter(k=>k[0]===profile.name).map(k=>k[1]);store(PREFIX+'drafts.'+profile.name,{version:1,items,guided});}
