 bindTask();restoreDraft();bindTaskNavigation();$('checkBtn').onclick=check;$('hintBtn').onclick=hint;$('revealBtn').onclick=reveal;$('backLesson').onclick=()=>openLesson(stageIndex);$('nextBtn').onclick=()=>i<3?openTask(i+1):finishStage();$('tryAgain').onclick=()=>{const h=hints;taskDrafts.delete(guidanceKey());openTask(i);hints=Math.max(1,h);};face();focusMain();
