function locked(){return solved||revealed;}
function rememberGrid(){gridPast.push([...value]);if(gridPast.length>100)gridPast.shift();gridFuture=[];}
function togglePoint(key){if(locked())return;rememberGrid();value=value.includes(key)?value.filter(x=>x!==key):[...value,key];updateGrid();}
