 main.querySelectorAll('[data-point]').forEach((b,i)=>{b.tabIndex=i===0?0:-1;b.dataset.coordinate=fa(i%9)+','+fa(Math.floor(i/9));b.addEventListener('focus',()=>{main.querySelectorAll('[data-point]').forEach(x=>x.tabIndex=x===b?0:-1);});});
 boardEl.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey){if(e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'gridRedo':'gridUndo').click();}return;}const peg=e.target.closest('[data-point]');if(!peg)return;const dirs={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]},d=dirs[e.key];if(!d)return;e.preventDefault();const [x,y]=peg.dataset.point.split(',').map(Number),nx=Math.max(0,Math.min(8,x+d[0])),ny=Math.max(0,Math.min(8,y+d[1]));main.querySelector(`[data-point="${nx},${ny}"]`).focus();});

